// Step 1: keep only new Apply matches, and make one calendar item per deadline
// (the deadline itself + a reminder two weeks before).
const body = $input.first().json.body;
const log = (message) => this.helpers.httpRequest({ method: 'POST', url: body.log_url, json: true, body: { scan_id: body.scan_id, message } });

const matches = (body.apply_opportunities || []);
await log(`n8n received ${matches.length} Apply matches for ${body.org_name}`);

const items = [];
for (const m of matches) {
  if (!m.deadline) continue;
  const due = new Date(m.deadline + 'T09:00:00');
  const remind = new Date(due.getTime() - 14 * 24 * 3600 * 1000);
  const end = (d) => new Date(d.getTime() + 30 * 60 * 1000).toISOString();
  const description = `${m.provider || ''}\nAmount: ${m.amount || 'see source'}\nSource: ${m.url}\nOpen in FundScout: ${m.app_link}\n\nDeadline found by FundScout: verify it on the source before relying on it.`;
  items.push({ json: { summary: `DUE: ${m.title}`, start: due.toISOString(), end: end(due), description } });
  if (remind > new Date()) items.push({ json: { summary: `Start application (due in 2 weeks): ${m.title}`, start: remind.toISOString(), end: end(remind), description } });
}
if (items.length === 0) {
  await log('No Apply matches have a stated deadline, so no calendar events this week');
  return [{ json: { skip: true } }]; // keeps the flow going so the email still sends
}
return items;

// Step 3: build the digest email.
const body = $('Scan finished (webhook)').first().json.body;
const log = (message) => this.helpers.httpRequest({ method: 'POST', url: body.log_url, json: true, body: { scan_id: body.scan_id, message } });

const created = $input.all().filter((i) => i.json && i.json.id && !i.json.error).length;
if (created) await log(`Added ${created} events to the calendar (deadlines + 2-week reminders)`);

// Demo: digest goes to real addresses only. Put your own email here if the club's contacts are placeholders.
const FALLBACK_TO = 'PUT_YOUR_EMAIL_HERE';
const real = (body.funding_contacts || []).filter((e) => !e.endsWith('@example.com'));
const to = (real.length ? real : [FALLBACK_TO]).join(',');

const rows = (body.apply_opportunities || []).map((m) => `<li><b><a href="${m.app_link}">${m.title}</a></b> (${m.provider || ''})<br>Amount: ${m.amount || 'see source'} · Deadline: ${m.deadline || 'see source'} <i>(verify on source)</i> · <a href="${m.url}">original source</a></li>`).join('');
const html = `<h2>FundScout weekly digest: ${body.org_name}</h2><p>Top matches worth applying for this week:</p><ul>${rows || '<li>No new Apply matches this week.</li>'}</ul><p style="color:#666">Sources checked this week: ${(body.sources_checked || []).join(', ')}.</p><p style="color:#666">FundScout never submits anything. Review each draft and submit it yourself.</p>`;
return [{ json: { to, subject: `FundScout: ${(body.apply_opportunities || []).length} funding matches for ${body.org_name}`, html } }];

// Step 5: report back so the step shows on FundScout's activity log.
const body = $('Scan finished (webhook)').first().json.body;
const to = $('3. Build digest email').first().json.to;
await this.helpers.httpRequest({ method: 'POST', url: body.log_url, json: true, body: { scan_id: body.scan_id, message: `Emailed the weekly digest to ${to}` } });
return $input.all();
